import {positionMath,validateDraft} from './math.js';
import {startMotion,drawPriceChart} from './motion.js';
const $=(s,r=document)=>r.querySelector(s),$$=(s,r=document)=>[...r.querySelectorAll(s)];
const escape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const price=(n,max)=>Number.isFinite(n)?'$'+n.toLocaleString('en-US',{minimumFractionDigits:n<.01?4:2,maximumFractionDigits:max??(n<.01?8:2)}):'—';
const compact=n=>Number.isFinite(n)?'$'+Intl.NumberFormat('en-US',{notation:'compact',maximumFractionDigits:2}).format(n):'—';
const percent=n=>Number.isFinite(n)?(n>=0?'+':'')+n.toFixed(2)+'%':'—';
const read=(key,fallback=[])=>{try{const v=JSON.parse(localStorage.getItem('solveil:'+key));return Array.isArray(fallback)?(Array.isArray(v)?v:fallback):(v&&typeof v==='object'?v:fallback);}catch{return fallback;}};
const write=(key,value)=>{try{localStorage.setItem('solveil:'+key,JSON.stringify(value));return true;}catch{toast('Local storage is full or unavailable. Export your draft instead.');return false;}};
let data=null,refreshing=false,wallet=null,walletProvider=null,connectedStandard=null,solBalance=null,positions=read('positions').filter(p=>['SOL','BTC','ETH'].includes(p.symbol)&&Number.isFinite(p.entry)&&Number.isFinite(p.margin)),watchlist=read('watchlist'),draftImage='',currentDraftId=null,appSymbol='SOL',appSide='long',appLeverage=3,appMargin=100,appRange=30,appTable='Market info',swapReversed=false,poolSavedOnly=false;
const market=symbol=>data?.markets?.find(m=>m.symbol===symbol);
let toastTimer;function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4200);}
function download(name,value){const blob=new Blob([JSON.stringify(value,null,2)],{type:'application/json'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),5000);}
async function copy(text){try{await navigator.clipboard.writeText(text);toast('Copied');}catch{toast('Copy is unavailable in this browser. Use Export JSON.');}}
const dateText=()=>data?.asOf?new Date(data.asOf).toLocaleTimeString('en-US',{hour:'2-digit',minute:'2-digit',second:'2-digit'}):'unavailable';
const sourceLabel=()=>`${data?.snapshot?'Saved snapshot':'Updated'} ${dateText()} · Binance reference / DexScreener pools`;
function applyMarketText(){
 $$('[data-price]').forEach(el=>el.textContent=price(market(el.dataset.price)?.price));$$('[data-change]').forEach(el=>{const n=market(el.dataset.change)?.change;el.textContent=percent(n);el.classList.toggle('bad',n<0);el.classList.toggle('good',n>=0);});
 $('#chain-status').textContent=data?.network?.slot?`SOLANA MAINNET · SLOT ${Number(data.network.slot).toLocaleString('en-US')}`:'SOLANA MAINNET · STATUS UNAVAILABLE';
 $('#market-state').textContent=sourceLabel();
 const tape=data?.tape||[];$('#trade-tape').innerHTML=tape.length?tape.slice(0,7).map(t=>`<div class="trade-row"><span class="${t.side==='Buy'?'good':'bad'}">${t.side}</span><span>${t.quantity.toFixed(3)} SOL</span><span>${t.price.toFixed(2)}</span><span class="muted">${new Date(t.time).toLocaleTimeString('en-GB',{hour12:false})}</span></div>`).join(''):'<p class="empty">Trade reference unavailable. No invented activity.</p>';
}
async function refreshData(){if(refreshing)return;refreshing=true;try{const res=await fetch('/api/markets',{cache:'no-store',signal:AbortSignal.timeout(18000)});if(!res.ok)throw Error();const next=await res.json();if(!Array.isArray(next.markets))throw Error();data=next;applyMarketText();motion.refresh();if(location.pathname.startsWith('/app/'))refreshAppValues();}catch{if(!data){$('#market-state').textContent='Market sources unavailable · try refresh in the app';$('#chain-status').textContent='SOLANA MAINNET · CONNECTION UNAVAILABLE';}}finally{refreshing=false;}}
const bins=$('#liquidity-bins');bins.innerHTML=Array.from({length:29},(_,i)=>`<i style="height:${14+Math.exp(-Math.pow((i-14)/5.6,2))*65+Math.sin(i*1.4)*5}%"></i>`).join('');
$$('[data-demo-tab]').forEach(b=>b.addEventListener('click',()=>{$$('[data-demo-tab]').forEach(el=>el.classList.toggle('active',el===b));bins.style.height=b.dataset.demoTab==='liquidity'?'150px':'';drawPriceChart($('#demo-chart'),market('SOL')?.candles||[]);}));
const configs=[{file:'launch.config.json',code:'{\n  "network": "solana:mainnet",\n  "name": "Your next idea",\n  "symbol": "IDEA",\n  "venue": "pump.fun",\n  "status": "local-draft",\n  "requiresWalletReview": true\n}'},{file:'your-launchpad.html',code:'<main class="your-world">\n  <h1>Your idea. Your market.</h1>\n\n  <!-- Keep the identity yours. -->\n  <a href="/app/launch">\n    Prepare a launch\n  </a>\n</main>'},{file:'launch-checklist.txt',code:'01  Confirm the name and ticker.\n02  Check the artwork and links.\n03  Export a copy of your draft.\n04  Open the chosen launch venue.\n05  Review its fees and token rules.\n06  Review and sign in your wallet.\n\nNo automatic signing. Your decision.'}];
let builderStep=0;function renderBuilder(){const config=configs[builderStep];$('#code-title').textContent=config.file;$('#builder-code').textContent=config.code;$$('[data-build]').forEach(b=>b.classList.toggle('active',Number(b.dataset.build)===builderStep));}
$$('[data-build]').forEach(b=>b.addEventListener('click',()=>{builderStep=Number(b.dataset.build);renderBuilder();}));$('#copy-config').addEventListener('click',()=>copy(configs[builderStep].code));renderBuilder();
$$('[data-control]').forEach(b=>b.addEventListener('click',()=>{$$('[data-control]').forEach(el=>el.classList.toggle('active',el===b));$('.flow-ring').style.stroke=['#80f4c6','#14f195','#ffffff'][Number(b.dataset.control)];}));
$('.menu').addEventListener('click',()=>$('.header').classList.toggle('menu-open'));addEventListener('scroll',()=>document.body.classList.toggle('scrolled',scrollY>15),{passive:true});
const wallets=new Map();function register(...items){for(const w of items)if(w&&typeof w.name==='string'&&w.features?.['standard:connect'])wallets.set(w.name,w);return()=>items.forEach(w=>wallets.delete(w.name));}const walletRegistry=Object.freeze({register});addEventListener('wallet-standard:register-wallet',event=>{if(typeof event.detail==='function')event.detail(walletRegistry);});dispatchEvent(new CustomEvent('wallet-standard:app-ready',{detail:walletRegistry}));
function updateWalletUI(){const title=wallet?wallet.slice(0,4)+'…'+wallet.slice(-4):'Connect wallet';$$('.connect').forEach(b=>b.textContent=title);if(location.pathname==='/app/wallet')renderApp();else if(location.pathname.startsWith('/app/'))refreshAppValues();}
async function readBalance(){solBalance=null;if(!wallet)return;try{const r=await fetch('/api/balance?address='+encodeURIComponent(wallet),{cache:'no-store',signal:AbortSignal.timeout(15000)});const j=await r.json();if(j.address===wallet&&Number.isFinite(j.lamports))solBalance=j.lamports/1e9;}catch{}updateWalletUI();}
function openWallet(){if(wallet){navigate('/app/wallet');return;}$('#wallet-message').textContent='';$('#wallet-modal').showModal();}
async function connectWallet(name){$('#wallet-message').textContent='Waiting for your wallet…';try{const discovered=[...wallets.values()].find(w=>w.name.toLowerCase().includes(name));let account;if(discovered){const result=await discovered.features['standard:connect'].connect();account=result.accounts.find(a=>a.chains?.some(c=>c.startsWith('solana:')));if(!account)throw Error('No Solana account was shared.');connectedStandard=discovered;walletProvider=null;}else if(name==='phantom'&&window.phantom?.solana?.isPhantom){walletProvider=window.phantom.solana;const result=await walletProvider.connect();account={address:result.publicKey.toString()};walletProvider.on?.('accountChanged',key=>{wallet=key?.toString()||null;solBalance=null;updateWalletUI();if(wallet)readBalance();});walletProvider.on?.('disconnect',()=>{wallet=null;solBalance=null;updateWalletUI();});}else{throw Error(`${name==='phantom'?'Phantom':'Backpack'} was not detected. Install its extension, then reload this page.`);}if(!/^[1-9A-HJ-NP-Za-km-z]{32,44}$/.test(account.address))throw Error('A valid Solana account was not shared.');wallet=account.address;$('#wallet-modal').close();updateWalletUI();readBalance();toast('Connected · public address only');}catch(e){$('#wallet-message').textContent=e.code===4001?'Connection cancelled.':e.message||'Wallet connection unavailable.';}}
$$('[data-wallet]').forEach(b=>b.addEventListener('click',()=>connectWallet(b.dataset.wallet)));$('[data-close-dialog]').addEventListener('click',()=>$('#wallet-modal').close());$('#wallet-modal').addEventListener('click',e=>{if(e.target===$('#wallet-modal'))$('#wallet-modal').close();});
document.addEventListener('click',e=>{const connect=e.target.closest('.connect');if(connect){e.preventDefault();openWallet();return;}const anchor=e.target.closest('a');if(!anchor||e.defaultPrevented||e.ctrlKey||e.metaKey||anchor.target==='_blank'||anchor.hasAttribute('download'))return;const url=new URL(anchor.href,location.href);if(url.origin===location.origin){if(url.pathname===location.pathname&&url.hash)return;if(['/','/docs','/developers'].includes(url.pathname)||url.pathname.startsWith('/app/')){e.preventDefault();navigate(url.pathname+url.search+url.hash);}}});
function navigate(url){history.pushState({},'',url);route();window.scrollTo({top:0,behavior:'instant'});$('.header').classList.remove('menu-open');}addEventListener('popstate',route);
function route(){const pathname=location.pathname,isApp=pathname.startsWith('/app/'),isDocs=['/docs','/developers'].includes(pathname);document.body.classList.toggle('in-app',isApp);document.body.classList.toggle('in-docs',isDocs);$('#home-view').classList.toggle('hidden',isApp||isDocs);$('#app-view').classList.toggle('hidden',!isApp);$('#docs-view').classList.toggle('hidden',!isDocs);$('.header-launch').classList.toggle('hidden',isApp);$('.header .connect').classList.toggle('hidden',!isApp);$('#top-nav').innerHTML=isApp?[['Perps','perps'],['Swap','swap'],['Pools','pools'],['Launches','launch'],['Wallet','wallet']].map(([label,slug])=>`<a href="/app/${slug}" class="${pathname.endsWith(slug)?'active':''}">${label}</a>`).join(''):'<a href="/docs">Docs</a><a href="/developers">Developers</a>';if(isApp)renderApp();if(isDocs)renderDocs(pathname==='/developers');document.title=(isApp?pathname.split('/').at(-1).replace(/^./,s=>s.toUpperCase())+' · ':isDocs?'Docs · ':'')+'Solveil';if(!isApp&&!isDocs)requestAnimationFrame(()=>motion.refresh());if(location.hash)setTimeout(()=>$(location.hash)?.scrollIntoView(),40);updateConnectText();}
function updateConnectText(){$$('.connect').forEach(b=>b.textContent=wallet?wallet.slice(0,4)+'…'+wallet.slice(-4):'Connect wallet');}
function coin(symbol){return `<span class="coin ${symbol.toLowerCase()}">${{SOL:'≋',BTC:'₿',ETH:'♦'}[symbol]||escape(symbol.slice(0,1))}</span>`;}
function marketSidebar(){return `<aside class="panel-stack"><div class="panel panel-pad"><h2>Markets <span class="pill" style="float:right">3</span></h2><input class="search-input" id="market-search" placeholder="⌕  Search markets" aria-label="Search markets"><div class="market-list">${['SOL','BTC','ETH'].map(symbol=>`<button class="market-pick ${appSymbol===symbol?'active':''}" data-symbol="${symbol}">${coin(symbol)}<div><strong>${symbol}-USD</strong><small data-market-price="${symbol}">${price(market(symbol)?.price)}</small></div><span data-market-change="${symbol}" class="${market(symbol)?.change<0?'bad':'good'}">${percent(market(symbol)?.change)}</span></button>`).join('')}</div></div><div class="panel panel-pad"><h3>Balances</h3><div class="balance-card">▣ &nbsp; Public wallet<div><span>SOL</span><b id="app-wallet-balance">${wallet?(solBalance===null?'Loading…':solBalance.toFixed(5)):'Not connected'}</b></div></div><p class="caption">Read-only wallet connection. No deposit is needed to use the simulator.</p></div><div class="panel panel-pad"><h3>Execution venue</h3><p class="caption">This workspace models positions. Open a Solana venue to place a real trade and review its terms.</p><a href="https://jup.ag/perps" target="_blank" rel="noopener" class="button">Explore Jupiter Perps ↗</a></div></aside>`;}
function renderPerps(){return `<div class="app-grid">${marketSidebar()}<div class="panel-stack"><div class="panel"><div class="app-chart-top"><div class="app-chart-title">${coin(appSymbol)}<strong>${appSymbol} / USD</strong><span class="pill">Reference</span><span id="app-current-price">${price(market(appSymbol)?.price)}</span></div><div class="ticker-stats"><div>24h high<strong id="app-high">—</strong></div><div>24h low<strong id="app-low">—</strong></div><div>24h change<strong id="app-change">—</strong></div><div>24h volume<strong id="app-volume">—</strong></div></div></div><div class="chart-controls"><div class="segments">${[1,7,14,30].map(n=>`<button data-range="${n}" class="${n===appRange?'active':''}">${n}D</button>`).join('')}</div><span class="pill mono">DAILY CLOSES</span></div><canvas id="app-chart" class="app-price-canvas" role="img" aria-label="${appSymbol} daily price history"></canvas><div class="chart-source" id="app-source">${escape(sourceLabel())}</div></div><div class="panel"><div class="table-tabs">${['Market info','Paper positions','History'].map(t=>`<button data-table="${t}" class="${t===appTable?'active':''}">${t}</button>`).join('')}</div><div id="app-table-content" class="table-content"></div></div></div><div class="panel panel-pad order-box"><h3>Model ${appSymbol}-USD <span class="pill mono">SIMULATION</span></h3><div class="order-badges"><span>Isolated model</span><span>No execution</span></div><div class="long-short"><button data-side="long" class="${appSide==='long'?'active':''}">Long</button><button data-side="short" class="short ${appSide==='short'?'active':''}">Short</button></div><div class="amount-label"><span>Hypothetical margin</span><span>Not your balance</span></div><div class="amount-box"><div class="amount-label"><label for="margin-input">Margin</label></div><div class="amount-value"><input id="margin-input" type="number" value="${appMargin}" min="0.1" max="1000000" step="1"><span>USDC</span></div></div><div class="leverage-label"><span>Leverage</span><b id="leverage-text">${appLeverage}×</b></div><div class="leverage-buttons">${[1,2,3,5].map(l=>`<button data-leverage="${l}" class="${appLeverage===l?'active':''}">${l}×</button>`).join('')}</div><div class="notice" style="margin-top:22px">A paper position only. No funds move, and no transaction is requested.</div><button id="save-position" class="button white">Save paper position</button><dl class="definition"><div><dt>Estimated liquidation</dt><dd id="calc-liq">—</dd></div><div><dt>Position size</dt><dd id="calc-size">—</dd></div><div><dt>Margin</dt><dd id="calc-margin">—</dd></div><div><dt>Move to liquidation</dt><dd id="calc-distance">—</dd></div><div><dt>Model maintenance</dt><dd>2%</dd></div></dl><p class="caption" style="margin-top:20px">Simplified model. Actual venue rules, fees, funding and slippage change the result. Leverage magnifies losses.</p></div></div>`;}
function renderTable(){const root=$('#app-table-content');if(!root)return;if(appTable==='Market info'){root.innerHTML=`<p>${escape(appSymbol)} daily closes from Binance (${escape(appSymbol)}USDT). USDC values in the model assume one dollar per USDC.</p><p class="caption">${escape(sourceLabel())}. Estimates exclude fees and funding. A saved paper position never creates a real order.</p>`;return;}if(!positions.length){root.innerHTML='No paper positions yet. Set a margin and leverage, then save a simulation.';return;}root.innerHTML=positions.slice().reverse().map(p=>{const calc=positionMath({...p,mark:market(p.symbol)?.price||p.entry});return `<div class="draft-item"><span><b>${escape(p.symbol)} ${escape(p.side)} · ${p.leverage}×</b><small>${price(p.margin)} margin · entry ${price(p.entry)} · ${new Date(p.createdAt).toLocaleDateString()}</small></span><span class="${calc?.pnl>=0?'good':'bad'}">${calc?(calc.liquidated?'Liquidation reached':price(calc.pnl)):'—'}</span><button data-remove-position="${escape(p.id)}" aria-label="Remove paper position">×</button></div>`;}).join('');$$('[data-remove-position]').forEach(b=>b.addEventListener('click',()=>{positions=positions.filter(p=>p.id!==b.dataset.removePosition);write('positions',positions);renderTable();}));}
function updateCalculator(){const p=positionMath({entry:market(appSymbol)?.price,mark:market(appSymbol)?.price,margin:appMargin,leverage:appLeverage,side:appSide});$('#calc-liq')&&($('#calc-liq').textContent=p?price(p.liquidation):'Enter a valid margin');$('#calc-size')&&($('#calc-size').textContent=p?price(p.size):'—');$('#calc-margin')&&($('#calc-margin').textContent=p?price(appMargin):'—');$('#calc-distance')&&($('#calc-distance').textContent=p?p.distance.toFixed(2)+'%':'—');const chart=$('#app-chart');if(chart)drawPriceChart(chart,(market(appSymbol)?.candles||[]).slice(-Math.max(2,appRange)),{entry:market(appSymbol)?.price,liquidation:p?.liquidation,side:appSide});}
function bindPerps(){$$('[data-symbol]').forEach(b=>b.addEventListener('click',()=>{appSymbol=b.dataset.symbol;renderApp();}));$('#market-search')?.addEventListener('input',e=>$$('[data-symbol]').forEach(b=>b.classList.toggle('hidden',!b.dataset.symbol.includes(e.target.value.toUpperCase()))));$$('[data-side]').forEach(b=>b.addEventListener('click',()=>{appSide=b.dataset.side;$$('[data-side]').forEach(el=>el.classList.toggle('active',el===b));updateCalculator();}));$$('[data-leverage]').forEach(b=>b.addEventListener('click',()=>{appLeverage=Number(b.dataset.leverage);$$('[data-leverage]').forEach(el=>el.classList.toggle('active',el===b));$('#leverage-text').textContent=appLeverage+'×';updateCalculator();}));$$('[data-range]').forEach(b=>b.addEventListener('click',()=>{appRange=Number(b.dataset.range);$$('[data-range]').forEach(el=>el.classList.toggle('active',el===b));updateCalculator();}));$('#margin-input').addEventListener('input',e=>{appMargin=Number(e.target.value);updateCalculator();});$('#save-position').addEventListener('click',()=>{const entry=market(appSymbol)?.price;if(!positionMath({entry,mark:entry,margin:appMargin,leverage:appLeverage,side:appSide})){toast('Enter a margin above zero, up to 1,000,000. A market price is required.');return;}positions.push({id:crypto.randomUUID(),symbol:appSymbol,side:appSide,leverage:appLeverage,entry,margin:appMargin,createdAt:new Date().toISOString()});positions=positions.slice(-30);write('positions',positions);appTable='Paper positions';$$('[data-table]').forEach(b=>b.classList.toggle('active',b.dataset.table===appTable));renderTable();toast('Paper position saved locally · no trade sent');});$$('[data-table]').forEach(b=>b.addEventListener('click',()=>{appTable=b.dataset.table;$$('[data-table]').forEach(el=>el.classList.toggle('active',el===b));renderTable();}));refreshAppValues();}
function poolCard(p){return `<article class="pool-card"><div class="pair">${p.image&&/^https:\/\//.test(p.image)?`<img loading="lazy" src="${escape(p.image)}" alt="" onerror="this.remove()">`:coin('SOL')}<h3>${escape(p.base.symbol)} / ${escape(p.quote.symbol)}</h3><span class="pill mono">${escape(p.dex)}</span><button class="save-pool" data-save-pool="${escape(p.id)}" aria-label="${watchlist.includes(p.id)?'Unsave':'Save'} pool">${watchlist.includes(p.id)?'★':'☆'}</button></div><div><span class="pool-price">${price(p.price)}</span><small class="${p.change<0?'bad':'good'}" style="float:right">${percent(p.change)}</small></div><div class="pool-metrics"><div>24h volume<strong>${compact(p.volume)}</strong></div><div>Liquidity<strong>${compact(p.liquidity)}</strong></div><div>24h buys<strong>${p.buys.toLocaleString()}</strong></div><div>24h sells<strong>${p.sells.toLocaleString()}</strong></div></div><div class="pool-actions"><span class="mono muted">${escape(p.id.slice(0,5))}…${escape(p.id.slice(-4))}</span><a href="${escape(p.url)}" target="_blank" rel="noopener">View pool ↗</a></div></article>`;}
function renderPools(){return `<div class="app-page"><div class="app-page-head"><div><p class="eyebrow mono">SOLANA / POOL DISCOVERY</p><h1>Every pool has a story.</h1><p>Real Solana pairs, ordered by 24-hour volume within the fetched sample.</p></div><button id="refresh-pools" class="button">Refresh ↻</button></div><div style="display:flex;justify-content:space-between;gap:15px;margin-bottom:20px;flex-wrap:wrap"><div class="segments"><button data-pool-tab="all" class="${poolSavedOnly?'':'active'}">All markets</button><button data-pool-tab="saved" class="${poolSavedOnly?'active':''}">Saved ${watchlist.length}</button></div><input class="search-input" id="pool-search" placeholder="Search symbol or pool address" aria-label="Search pools" style="width:280px;margin:0"></div><p class="inline-status">${escape(sourceLabel())}</p><div class="pool-grid" id="pool-cards"></div></div>`;}
function updatePools(filter=''){const root=$('#pool-cards');if(!root)return;const pools=(data?.pools||[]).filter(p=>(!poolSavedOnly||watchlist.includes(p.id))&&`${p.base.symbol} ${p.quote.symbol} ${p.dex} ${p.id}`.toLowerCase().includes(filter.toLowerCase()));root.innerHTML=pools.length?pools.map(poolCard).join(''):`<div class="panel empty">${data?'No pools match this view.':'Loading public Solana pools…'}</div>`;$$('[data-save-pool]').forEach(b=>b.addEventListener('click',()=>{watchlist=watchlist.includes(b.dataset.savePool)?watchlist.filter(id=>id!==b.dataset.savePool):[...watchlist,b.dataset.savePool];write('watchlist',watchlist);updatePools($('#pool-search')?.value||'');$$('[data-pool-tab="saved"]').forEach(el=>el.textContent='Saved '+watchlist.length);}));}
function bindPools(){$('#pool-search').addEventListener('input',e=>updatePools(e.target.value));$('#refresh-pools').addEventListener('click',async()=>{toast('Refreshing public sources…');await refreshData();updatePools($('#pool-search')?.value||'');});$$('[data-pool-tab]').forEach(b=>b.addEventListener('click',()=>{poolSavedOnly=b.dataset.poolTab==='saved';$$('[data-pool-tab]').forEach(el=>el.classList.toggle('active',el===b));updatePools($('#pool-search')?.value||'');}));updatePools();}
function renderSwap(){return `<div class="app-page"><div class="app-page-head"><div><p class="eyebrow mono">SWAP / SOLANA</p><h1>A clear route to your next token.</h1><p>Estimate here. Review the executable quote on Jupiter.</p></div></div><div class="swap-layout"><div class="panel swap-main"><h2>Swap</h2><div class="amount-box"><div class="amount-label">You pay</div><div class="amount-value"><input id="swap-amount" type="number" min="0" step="any" value="1" aria-label="Swap amount"><span id="swap-from">${swapReversed?'USDC':'SOL'}</span></div></div><button class="swap-arrow" id="swap-reverse" aria-label="Reverse swap direction">⇅</button><div class="amount-box"><div class="amount-label">Indicative output</div><div class="amount-value"><strong id="swap-output" style="font-size:30px;font-weight:400">—</strong><span id="swap-to" style="margin-left:auto">${swapReversed?'SOL':'USDC'}</span></div></div><dl class="definition"><div><dt>Reference</dt><dd id="swap-reference">—</dd></div><div><dt>Network</dt><dd>Solana</dd></div><div><dt>Execution</dt><dd>On Jupiter</dd></div></dl><a href="https://jup.ag/swap/${swapReversed?'USDC-SOL':'SOL-USDC'}" target="_blank" rel="noopener" class="button white" id="jupiter-swap" style="display:flex;margin-top:20px">Get a live quote on Jupiter ↗</a><p class="caption" style="margin-top:14px">The estimate assumes USDC = $1 and excludes fees, slippage and routing. Jupiter calculates the final quote. No swap is sent here.</p></div><aside class="swap-help"><p class="eyebrow mono">YOUR WALLET, YOUR REVIEW</p><h3>Before you sign.</h3><p>Check the tokens, network, route, amount and minimum received on the execution venue.</p><p>This preview never asks for a private key or an approval to move funds.</p><a href="/docs#status" class="text-link">What works in this version ↗</a></aside></div></div>`;}
function updateSwap(){const input=Number($('#swap-amount')?.value),p=market('SOL')?.price;const valid=Number.isFinite(input)&&input>=0&&input<=1e9&&p>0;$('#swap-output')&&($('#swap-output').textContent=valid?(swapReversed?input/p:input*p).toLocaleString('en-US',{maximumFractionDigits:6}):'—');$('#swap-reference')&&($('#swap-reference').textContent=price(p)+' / SOL');}
function bindSwap(){$('#swap-amount').addEventListener('input',updateSwap);$('#swap-reverse').addEventListener('click',()=>{swapReversed=!swapReversed;renderApp();});updateSwap();}
function formDraft(){return {name:$('#token-name')?.value||'',symbol:$('#token-symbol')?.value||'',description:$('#token-description')?.value||'',website:$('#token-website')?.value||'',social:$('#token-social')?.value||'',image:draftImage};}
function renderLaunch(){const working=read('working-draft',{});draftImage=working.image||'';return `<div class="app-page"><div class="app-page-head"><div><p class="eyebrow mono">LAUNCH / PREPARATION</p><h1>Give your idea its first block.</h1><p>Build the draft here. Create the token on pump.fun after reviewing its launch rules.</p></div><label class="button" style="cursor:pointer">Import draft<input id="import-draft" type="file" accept="application/json,.json" hidden></label></div><div class="form-grid"><form class="panel launch-form" id="launch-form"><label class="upload" for="token-image"><img id="upload-preview" src="${draftImage?escape(draftImage):'/assets/mark-blue.svg'}" alt="Token artwork preview"><span><strong>Drop an image or click</strong><small>PNG, JPG or WebP · under 1.3 MB</small></span><input id="token-image" type="file" accept="image/png,image/jpeg,image/webp" hidden></label><div class="field-row"><label class="field-label">Name<input class="field" id="token-name" maxlength="32" placeholder="Your coin name" required value="${escape(working.name||'')}"></label><label class="field-label">Ticker<input class="field" id="token-symbol" maxlength="10" placeholder="TICKER" required value="${escape(working.symbol||'')}"></label></div><label class="field-label">Description<textarea class="field" id="token-description" maxlength="500" placeholder="What is your coin about?">${escape(working.description||'')}</textarea></label><div class="field-row"><label class="field-label">Website (optional)<input class="field" id="token-website" type="url" placeholder="https://" value="${escape(working.website||'')}"></label><label class="field-label">X (optional)<input class="field" id="token-social" type="url" placeholder="https://x.com/yourproject" value="${escape(working.social||'')}"></label></div><div class="notice">This saves a local launch plan. The token, mint address and liquidity are created by the launch venue after your own review and signature.</div><div class="draft-actions"><button class="button white" type="submit">Save draft</button><button class="button" id="export-draft" type="button">Export JSON ↗</button><button class="button" id="copy-draft" type="button">Copy details</button></div></form><div class="panel-stack"><div class="panel panel-pad"><div class="launch-preview-art" id="launch-preview-art"></div><div class="preview-copy"><span class="pill mono">LOCAL DRAFT</span><h3 id="preview-name">Your token</h3><p id="preview-symbol">$TICKER · Solana</p><p id="preview-description">Your idea starts here.</p></div><a href="https://pump.fun/create" class="button white" target="_blank" rel="noopener" style="width:100%">Continue on pump.fun ↗</a><p class="caption" style="margin:13px 0 0">Use your exported or copied details in the venue's form. Nothing is automatically submitted.</p></div><div class="panel panel-pad"><h3>Your drafts</h3><div id="draft-list"></div></div></div></div></div>`;}
function previewDraft(){const d=formDraft();$('#preview-name').textContent=d.name||'Your token';$('#preview-symbol').textContent='$'+(d.symbol.toUpperCase()||'TICKER')+' · Solana';$('#preview-description').textContent=d.description||'Your idea starts here.';$('#launch-preview-art').innerHTML=d.image?`<img src="${escape(d.image)}" alt="Token artwork">`:`<span class="preview-initial">${escape(d.symbol.slice(0,1).toUpperCase()||'↗')}</span>`;$('#upload-preview').src=d.image||'/assets/mark-blue.svg';write('working-draft',d);}
function draftList(){const drafts=read('drafts').filter(d=>d.id&&validateDraft(d).value);$('#draft-list').innerHTML=drafts.length?drafts.map(d=>`<div class="draft-item"><span><b>${escape(d.name)}</b><small>$${escape(d.symbol)}</small></span><button type="button" data-open-draft="${escape(d.id)}">Open ↗</button><button type="button" data-delete-draft="${escape(d.id)}" aria-label="Delete local draft">×</button></div>`).join(''):'<p class="caption">No saved drafts yet.</p>';$$('[data-open-draft]').forEach(b=>b.addEventListener('click',()=>{const d=drafts.find(v=>v.id===b.dataset.openDraft);if(!d)return;write('working-draft',d);currentDraftId=d.id;renderApp();toast('Draft opened');}));$$('[data-delete-draft]').forEach(b=>b.addEventListener('click',()=>{const next=drafts.filter(d=>d.id!==b.dataset.deleteDraft);write('drafts',next);if(currentDraftId===b.dataset.deleteDraft)currentDraftId=null;draftList();toast('Local draft deleted');}));}
function validCurrent(){const r=validateDraft(formDraft());if(r.error){toast(r.error);return null;}return r.value;}
function bindLaunch(){$('#launch-form').addEventListener('input',previewDraft);$('#launch-form').addEventListener('submit',e=>{e.preventDefault();const d=validCurrent();if(!d)return;const saved={...d,id:currentDraftId||crypto.randomUUID(),updatedAt:new Date().toISOString(),network:'solana:mainnet',status:'local-draft'};const drafts=read('drafts').filter(v=>v.id!==saved.id).slice(-9);if(write('drafts',[...drafts,saved])){currentDraftId=saved.id;draftList();toast('Draft saved locally · no token created');}});$('#export-draft').addEventListener('click',()=>{const d=validCurrent();if(d)download(d.symbol.toLowerCase()+'-launch-draft.json',{...d,network:'solana:mainnet',status:'local-draft'});});$('#copy-draft').addEventListener('click',()=>{const d=validCurrent();if(d)copy(`${d.name} ($${d.symbol})\n\n${d.description}\n\n${d.website}\n${d.social}`);});$('#token-image').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>1300000){toast('Choose a PNG, JPG or WebP under 1.3 MB.');return;}const reader=new FileReader();reader.onload=()=>{draftImage=String(reader.result);previewDraft();};reader.readAsDataURL(file);});const upload=$('.upload');upload.addEventListener('dragover',e=>e.preventDefault());upload.addEventListener('drop',e=>{e.preventDefault();const file=e.dataTransfer.files[0];if(!file||!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>1300000){toast('Choose a PNG, JPG or WebP under 1.3 MB.');return;}const reader=new FileReader();reader.onload=()=>{draftImage=String(reader.result);previewDraft();};reader.readAsDataURL(file);});$('#import-draft').addEventListener('change',async e=>{const file=e.target.files[0];if(!file)return;if(file.size>2000000){toast('Draft file is too large.');return;}try{const input=JSON.parse(await file.text());const result=validateDraft(input);if(!result.value)throw Error(result.error);write('working-draft',result.value);currentDraftId=null;renderApp();toast('Draft imported · not published');}catch(error){toast(error.message||'Invalid draft JSON.');}});previewDraft();draftList();}
function renderWallet(){return `<div class="app-page wallet-page"><p class="eyebrow mono">YOUR WALLET / SOLANA</p><div class="app-page-head"><div><h1>Keep the keys.<br>See the balance.</h1><p>A public account view, without signing or depositing.</p></div></div><div class="panel"><h3>Public wallet</h3>${wallet?`<p class="wallet-address">${escape(wallet)}</p><div class="wallet-total">${solBalance===null?'—':solBalance.toLocaleString('en-US',{maximumFractionDigits:6})} <span class="muted" style="font-size:20px">SOL</span></div><p class="caption">${solBalance===null?'Balance temporarily unavailable.':'Confirmed balance from Solana mainnet RPC.'}</p><div class="draft-actions"><a href="https://explorer.solana.com/address/${encodeURIComponent(wallet)}" class="button" target="_blank" rel="noopener">View on explorer ↗</a><button id="refresh-balance" class="button">Refresh ↻</button><button id="disconnect-wallet" class="button">Disconnect</button></div>`:'<p class="caption">Connect your Phantom or Backpack wallet to view its public Solana address and SOL balance.</p><button class="button white connect">Connect wallet</button>'}</div><div class="notice" style="margin-top:16px">This preview has no deposit address and no shielded vault. We never ask for your recovery phrase or private key.</div></div>`;}
function renderApp(){const page=location.pathname.split('/').filter(Boolean)[1]||'perps';const root=$('#app-view');root.innerHTML=page==='pools'?renderPools():page==='swap'?renderSwap():page==='launch'?renderLaunch():page==='wallet'?renderWallet():renderPerps();if(page==='pools')bindPools();else if(page==='swap')bindSwap();else if(page==='launch')bindLaunch();else if(page==='wallet'){if(wallet){$('#refresh-balance').addEventListener('click',readBalance);$('#disconnect-wallet').addEventListener('click',async()=>{try{if(connectedStandard?.features?.['standard:disconnect'])await connectedStandard.features['standard:disconnect'].disconnect();else await walletProvider?.disconnect?.();}catch{}wallet=null;walletProvider=null;connectedStandard=null;solBalance=null;updateWalletUI();toast('Disconnected');});}}else bindPerps();updateConnectText();}
function refreshAppValues(){if($('#app-chart')){const m=market(appSymbol);$('#app-current-price').textContent=price(m?.price);$('#app-high').textContent=price(m?.high);$('#app-low').textContent=price(m?.low);$('#app-change').textContent=percent(m?.change);$('#app-volume').textContent=compact(m?.volume);$('#app-source').textContent=sourceLabel();$$('[data-market-price]').forEach(el=>el.textContent=price(market(el.dataset.marketPrice)?.price));$$('[data-market-change]').forEach(el=>{const change=market(el.dataset.marketChange)?.change;el.textContent=percent(change);el.classList.toggle('bad',change<0);el.classList.toggle('good',change>=0);});if($('#app-wallet-balance'))$('#app-wallet-balance').textContent=wallet?(solBalance===null?'Unavailable':solBalance.toFixed(5)):'Not connected';updateCalculator();renderTable();}if($('#pool-cards')){updatePools($('#pool-search')?.value||'');$('.inline-status').textContent=sourceLabel();}if($('#swap-output'))updateSwap();}
function renderDocs(developer=false){$('#docs-view').innerHTML=`<div class="wrap docs-layout"><nav class="docs-sidebar"><strong>FOR EVERYONE</strong><a href="/docs">Overview</a><a href="/docs#status">Product status</a><a href="/docs#sources">Data sources</a><a href="/docs#wallet">Wallet connection</a><a href="/docs#risk">Model limits</a><strong>FOR BUILDERS</strong><a href="/developers">Developer notes</a><a href="/app/launch">Launch draft studio</a></nav><article class="docs-content">${developer?`<p class="eyebrow mono">DEVELOPERS</p><h1>A Solana workspace.<br><em>Clear boundaries.</em></h1><p>Solveil is a visual preview and public-data workspace. It is independent of Curveil and does not operate Curveil's contracts on Solana.</p><h2>Public market endpoint</h2><p><code>GET /api/markets</code> reads SOL, BTC and ETH market context, a Solana pool sample and the Solana slot. The response contains a source timestamp and a <code>snapshot</code> flag when only saved data is available.</p><pre>{\n  "asOf": "ISO source retrieval time",\n  "snapshot": false,\n  "markets": [],\n  "pools": [],\n  "tape": [],\n  "network": { "slot": 0 }\n}</pre><h2>Launch drafts</h2><p>Drafts are stored in this browser, never broadcast as token launches. Export/import supports a token name, ticker, description, HTTPS links and an optional PNG/JPEG/WebP image. The venue performs the real launch.</p><h2>Wallet model</h2><p>Wallet Standard discovery and Phantom's Solana provider are used for public-address connection. <code>GET /api/balance?address=...</code> reads a confirmed native SOL balance. There is no message signing, private-key collection, custodial account or transaction broadcast endpoint.</p><h2>Execution integrations</h2><p>Swaps hand off to <a href="https://jup.ag/swap" target="_blank" rel="noopener">Jupiter</a>. Launch drafts hand off to <a href="https://pump.fun/create" target="_blank" rel="noopener">pump.fun</a>. Pool links come from the returned DexScreener pair data. This preview has no custom mint factory, fee splitter or shielded Solana program.</p>`:`<p class="eyebrow mono">OVERVIEW</p><h1>Open markets.<br><em>Solana native.</em></h1><p>One place to explore public markets, understand a hypothetical position and prepare a launch. Solveil is a working-name preview, with a recreated visual template adapted to Solana.</p><h2 id="status">What works today</h2><table><thead><tr><th>Feature</th><th>Current behavior</th></tr></thead><tbody><tr><td>Public markets</td><td>API-backed reference prices and Solana pool discovery.</td></tr><tr><td>Wallet</td><td>Public Solana address and native SOL balance only.</td></tr><tr><td>Perps</td><td>Local simulation. No order is opened.</td></tr><tr><td>Swap</td><td>Indicative calculation and explicit Jupiter handoff.</td></tr><tr><td>Launches</td><td>Local drafts, image preview, JSON import/export and pump.fun handoff.</td></tr><tr><td>Privacy vault</td><td>Not implemented. No private-transfer or shielding claim.</td></tr><tr><td>Project token</td><td>No mint supplied. CA soon.</td></tr></tbody></table><h2 id="sources">Where the data comes from</h2><p>Prices, daily candles and SOL/USDT trade references come from Binance's public market-data API. They are exchange reference prices, not executions by this application. Pool liquidity, volume and pair links come from <a href="https://docs.dexscreener.com/api/reference" target="_blank" rel="noopener">DexScreener</a>, filtered to Solana. The pool list is a fetched sample, not the entire chain.</p><p>Data is refreshed every 30 seconds while this page is visible. If a source fails, saved data is explicitly marked as a snapshot with its original retrieval time; unavailable fields show a dash.</p><h2 id="wallet">Connecting your wallet</h2><p>Use a Solana wallet such as Phantom or a Wallet Standard-compatible Backpack installation. Connection shares your public address. Reading the SOL balance sends that address to Solana's public RPC. No signature is needed and no funds move.</p><h2 id="risk">Model limits</h2><p>The paper model uses a fixed 2% maintenance margin and ignores fees, funding, slippage, oracle differences, collateral changes and venue rules. Its liquidation estimate is educational. Saved positions are local simulations, not claims on real assets.</p><p>The launch lifecycle and liquidity distribution on the home page are visual explanations. They are not live token launches or audited liquidity rules. Actual terms, fees and signing happen on the external venue you choose.</p><h2>Independent by design</h2><p>Solveil is not affiliated with Curveil, Solana Foundation, Jupiter, Binance or pump.fun. No official X account or token address has been assigned.</p>`}</article></div>`;}
const motion=startMotion(()=>data);route();refreshData();setInterval(()=>{if(!document.hidden)refreshData();},30000);addEventListener('resize',()=>{motion.refresh();if($('#app-chart'))updateCalculator();});
